begin;
create temporary table voice_fixture(owner_id uuid,speaker_id uuid,other_id uuid,community_id uuid,channel_id uuid)on commit drop;
insert into voice_fixture select gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid();grant select on voice_fixture to authenticated,anon;
insert into auth.users(id,aud,role,email,raw_user_meta_data,raw_app_meta_data,created_at,updated_at)select u,'authenticated','authenticated','qa-'||u||'@example.invalid',jsonb_build_object('display_name','QA_'||substr(replace(u::text,'-',''),1,16)),'{}'::jsonb,now(),now()from voice_fixture cross join lateral unnest(array[owner_id,speaker_id,other_id])u;
insert into public.communities(id,name,created_by)select community_id,'QA voice',owner_id from voice_fixture;
insert into public.channels(id,community_id,name,kind,created_by)select channel_id,community_id,'QA voice','voice',owner_id from voice_fixture;
insert into public.site_roles(user_id,role)select owner_id,'creator'from voice_fixture;
set local role authenticated;
do $$declare f record;denied boolean;begin select * into f from voice_fixture;perform set_config('request.jwt.claim.sub',f.speaker_id::text,true);
 denied:=false;begin insert into public.call_transcripts(room_sid,room_name,speaker_id,content)values('RM_fixture','channel-'||f.channel_id,f.speaker_id,'No consent');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'No consent accepted';end if;
 insert into public.voice_consents(user_id,room_sid,room_name,accepted)values(f.speaker_id,'RM_fixture','channel-'||f.channel_id,true);
 insert into public.call_transcripts(room_sid,room_name,speaker_id,content)values('RM_fixture','channel-'||f.channel_id,f.speaker_id,'Own consented speech');
 if exists(select 1 from public.call_transcripts)then raise exception'Non-admin read transcripts';end if;
 denied:=false;begin insert into public.call_transcripts(room_sid,room_name,speaker_id,content)values('RM_fixture','channel-'||f.channel_id,f.other_id,'Forged speaker');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Speaker spoof allowed';end if;
 perform public.reserve_luladroid('RM_fixture','channel-'||f.channel_id);
 denied:=false;begin perform public.reserve_luladroid('RM_fixture','channel-'||f.channel_id);exception when others then denied:=true;end;if not denied then raise exception'Budget throttle missing';end if;
 update public.voice_consents set accepted=false where user_id=f.speaker_id;
 denied:=false;begin insert into public.call_transcripts(room_sid,room_name,speaker_id,content)values('RM_fixture','channel-'||f.channel_id,f.speaker_id,'Revoked');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Revoked consent accepted';end if;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);if(select count(*)from public.call_transcripts where room_sid='RM_fixture')<>1 then raise exception'Admin cannot review';end if;
end $$;
reset role;
rollback;
